-- ─────────────────────────────────────────────────────────────────────────────
-- V13: barcodes nobody could answer, and the views that show the catalog's
-- coverage (docs/plans/food-data-import.md "Scan-miss measurement",
-- docs/plans/screens/barcode.md).
--
-- `barcode_lookups` (V7) already records every lookup's outcome server-side,
-- which is enough for the hit rate. What it cannot say is where the misses
-- come from, so the 0.2 app reports each miss once, after a 404, through
-- POST /v1/foods/barcode-misses. One row per report:
--   id           generated by the app, so a retried report is the same row
--   barcode      the code as scanned
--   gtin         its 14-digit GTIN (null when the check digit fails), computed
--                by the server with the importers' rule, so misses group with
--                the way Branded Foods and Open Food Facts rows are stored
--   country      the phone's region setting (X-Country-Code), two letters
--   platform     android, ios or other (X-Platform)
--   app_version  X-App-Version
--
-- No user_id, install id or session id, on purpose: any of them would let the
-- rows be joined into one person's shopping list. The views aggregate by day,
-- product and region, so no view can show one person's scans either. A
-- barcode names a product, not a person, and the region is a setting the
-- person chose, not a location.
--
-- Additive and idempotent (IF NOT EXISTS, CREATE OR REPLACE), so running it
-- twice, or against a database that got it by hand first, changes nothing.
-- RLS on with no policies, as on every table.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS barcode_misses (
    id          UUID PRIMARY KEY,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    barcode     TEXT NOT NULL CHECK (barcode ~ '^[0-9]{8,14}$'),
    gtin        TEXT CHECK (gtin ~ '^[0-9]{14}$'),
    country     TEXT CHECK (country ~ '^[A-Z]{2}$'),
    platform    TEXT NOT NULL CHECK (platform IN ('android', 'ios', 'other')),
    app_version TEXT CHECK (char_length(app_version) <= 32)
);

CREATE INDEX IF NOT EXISTS barcode_misses_created_at_idx ON barcode_misses (created_at);

ALTER TABLE barcode_misses ENABLE ROW LEVEL SECURITY;

-- Barcode hit rate per day. A hit is any source answering (our catalog, Open
-- Food Facts, Nutritionix); errors are lookups no source could answer at all,
-- so they say nothing about coverage and stay out of the rate.
CREATE OR REPLACE VIEW analytics.barcode_hit_rate_daily AS
SELECT
    (at AT TIME ZONE 'UTC')::date AS day,
    count(*) AS lookups,
    count(*) FILTER (WHERE outcome <> 'miss' AND outcome <> 'error') AS hits,
    count(*) FILTER (WHERE outcome = 'miss') AS misses,
    count(*) FILTER (WHERE outcome = 'error') AS errors,
    round(
        count(*) FILTER (WHERE outcome <> 'miss' AND outcome <> 'error')::numeric
            / nullif(count(*) FILTER (WHERE outcome <> 'error'), 0),
        4
    ) AS hit_rate
FROM public.barcode_lookups
GROUP BY 1;

-- The products people scan and we don't have, last 30 days, grouped on the
-- GTIN so a UPC-A and its EAN-13 count as one product.
CREATE OR REPLACE VIEW analytics.top_missed_barcodes AS
SELECT
    coalesce(gtin, barcode) AS code,
    count(*) AS misses,
    count(DISTINCT country) AS countries,
    max(created_at) AS last_missed_at
FROM public.barcode_misses
WHERE created_at > now() - interval '30 days'
GROUP BY 1
ORDER BY misses DESC, code
LIMIT 100;

-- Misses per day by the phone's region. Tells us which country's data to add next.
CREATE OR REPLACE VIEW analytics.barcode_misses_by_country AS
SELECT
    (created_at AT TIME ZONE 'UTC')::date AS day,
    coalesce(country, 'unknown') AS country,
    count(*) AS misses
FROM public.barcode_misses
GROUP BY 1, 2;

-- V9's default privileges already cover views created by the migration role;
-- granted explicitly so a database where someone else ran this still works.
GRANT SELECT ON analytics.barcode_hit_rate_daily, analytics.top_missed_barcodes,
    analytics.barcode_misses_by_country TO grafana_ro;
